dist.vi_du:
function khiBatDau() {
  taoKhung(100, 100);

  toMauNen(200);

  // Set the coordinates.
  let x1 = 10;
  let y1 = 50;
  let x2 = 90;
  let y2 = 50;

  // Draw the points and a line connecting them.
  veDuongThang(x1, y1, x2, y2);
  doDayNet(5);
  veDiem(x1, y1);
  veDiem(x2, y2);

  // Calculate the distance.
  let d = khoangCach(x1, y1, x2, y2);

  // Style the text.
  canLeVanBan(GIUA);
  coChuVanBan(16);

  // Display the distance.
  veVanBan(d, 43, 40);

  moTa('Two dots connected by a horizontal line. The number 80 is written above the center of the line.');
}

