  }
}

push.vi_du:
function khiBatDau() {
  taoKhung(100, 100);

  toMauNen(200);

  // Draw the left circle.
  veHinhTron(25, 50, 20);

  // Begin the drawing group.
  luuTrangThai();

  // Translate the origin to the center.
  dichChuyen(50, 50);

  // Style the circle.
  doDayNet(5);
  mauNet('royalblue');
  mauTo('orange');

  // Draw the circle.
  veHinhTron(0, 0, 20);

  // End the drawing group.
  phucHoiTrangThai();

  // Draw the right circle.
  veHinhTron(75, 50, 20);

  moTa(
    'Three circles drawn in a row on a gray background. The left and right circles are white with thin, black borders. The middle circle is orange with a thick, blue border.'
  );
}

