frameRate.vi_du:
function khiBatDau() {
  taoKhung(100, 100);

  moTa('A white circle on a gray background. The circle moves from left to right in a loop. It slows down when the mouse is pressed.');
}

function khiVe() {
  toMauNen(200);

  // Set the x variable based
  // on the current frameCount.
  let x = soKhungHinh % 100;

  // If the mouse is pressed,
  // decrease the frame rate.
  if (dangNhanChuot === true) {
    tocDoKhungHinh(10);
  } else {
    tocDoKhungHinh(60);
  }

  // Use x to set the circle's
  // position.
  veHinhTron(x, 50, 20);
}

