  taoKhung(100, 100);

  toMauNen(200);

  // Create a p5.Image object.
  let img = taoAnh(66, 66);

  // Load the image's pixels into memory.
  img.taiDiemAnh();

  // Set all the image's pixels to black.
  for (let x = 0; x < img.doRong; x += 1) {
    for (let y = 0; y < img.doCao; y += 1) {
      img.datDiemAnh(x, y, 0);
    }
  }

  // Update the image's pixel values.
  img.capNhatDiemAnh();

  // Draw the image.
  veAnh(img, 17, 17);

  moTa('A black square drawn in the middle of a gray square.');
}

