bezierTangent.vi_du:
function khiBatDau() {
  taoKhung(100, 100);

  toMauNen(200);

  // Set the coordinates for the curve's anchor and control points.
  let x1 = 85;
  let x2 = 10;
  let x3 = 90;
  let x4 = 15;
  let y1 = 20;
  let y2 = 10;
  let y3 = 90;
  let y4 = 80;

  // Style the curve.
  khongTo();

  // Draw the curve.
  veDuongBezier(x1, y1, x2, y2, x3, y3, x4, y4);

  // Draw tangents along the curve's path.
  mauTo(255);

  // Top-right circle.
  mauNet(0);
  let x = diemBezier(x1, x2, x3, x4, 0);
  let y = diemBezier(y1, y2, y3, y4, 0);
  veHinhTron(x, y, 5);

  // Top-right tangent line.
  // Scale the tangent point to draw a shorter line.
  mauNet(255, 0, 0);
  let tx = 0.1 * tiepTuyenBezier(x1, x2, x3, x4, 0);
  let ty = 0.1 * tiepTuyenBezier(y1, y2, y3, y4, 0);
  veDuongThang(x + tx, y + ty, x - tx, y - ty);

  // Center circle.
  mauNet(0);
  x = diemBezier(x1, x2, x3, x4, 0.5);
  y = diemBezier(y1, y2, y3, y4, 0.5);
  veHinhTron(x, y, 5);

  // Center tangent line.
  // Scale the tangent point to draw a shorter line.
  mauNet(255, 0, 0);
  tx = 0.1 * tiepTuyenBezier(x1, x2, x3, x4, 0.5);
  ty = 0.1 * tiepTuyenBezier(y1, y2, y3, y4, 0.5);
  veDuongThang(x + tx, y + ty, x - tx, y - ty);

  // Bottom-left circle.
  mauNet(0);
  x = diemBezier(x1, x2, x3, x4, 1);
  y = diemBezier(y1, y2, y3, y4, 1);
  veHinhTron(x, y, 5);

  // Bottom-left tangent.
  // Scale the tangent point to draw a shorter line.
  mauNet(255, 0, 0);
  tx = 0.1 * tiepTuyenBezier(x1, x2, x3, x4, 1);
  ty = 0.1 * tiepTuyenBezier(y1, y2, y3, y4, 1);
  veDuongThang(x + tx, y + ty, x - tx, y - ty);

  moTa(
    'A black s-curve on a gray square. The endpoints and center of the curve are marked with white circles. Red tangent lines extend from the white circles.'
  );
}

