  mauNet(0);
  doDayNet(2);
  veDuongSpline(x1, y1, x2, y2, x3, y3, x4, y4);

  const t = 0.5 + 0.5 * sin(soKhungHinh * 0.03);

  const px = diemSpline(x1, x2, x3, x4, t);
  const py = diemSpline(y1, y2, y3, y4, t);

  let tx = tiepTuyenSpline(x1, x2, x3, x4, t);
  let ty = tiepTuyenSpline(y1, y2, y3, y4, t);

  const m = Math.hypot(tx, ty) || 1;
  tx = (tx / m) * 16;
  ty = (ty / m) * 16;

  mauNet(0);
  doDayNet(2);
  veDuongThang(px, py, px + tx, py + ty);

  khongNet();
  mauTo('red');
  veHinhTron(px, py, 7);
}

