let img;

async function khiBatDau() {
  // Load the image.
  img = await taiAnh('assets/rockies.jpg');

  taoKhung(100, 100);

  // Display the image.
  veAnh(img, 0, 0, 100, 100);

  // Get the pixel density.
  let d = matDoDiemAnh();

  // Calculate the halfway index in the pixels array.
  let halfImage = 4 * (d * doRong) * (d * doCao / 2);

  // Load the pixels array.
  taiDiemAnh();

  // Copy the top half of the canvas to the bottom.
  for (let i = 0; i < halfImage; i += 1) {
    mangDiemAnh[i + halfImage] = mangDiemAnh[i];
  }

  // Update the canvas.
  capNhatDiemAnh();

  moTa('Two identical images of mountain landscapes, one on top of the other.');
}

