function khiBatDau() {
  taoKhung(100, 100);
  toMauNen(128);

  // Load the pixels array.
  taiDiemAnh();

  // Set the dot's coordinates.
  let x = 50;
  let y = 50;

  // Get the pixel density.
  let d = matDoDiemAnh();

  // Set the pixel(s) at the center of the canvas black.
  for (let i = 0; i < d; i += 1) {
    for (let j = 0; j < d; j += 1) {
      let index = 4 * ((y * d + j) * doRong * d + (x * d + i));
      // Red.
      mangDiemAnh[index] = 0;
      // Green.
      mangDiemAnh[index + 1] = 0;
      // Blue.
      mangDiemAnh[index + 2] = 0;
      // Alpha.
      mangDiemAnh[index + 3] = 255;
    }
  }

  // Update the canvas.
  capNhatDiemAnh();

  moTa('A black dot in the middle of a gray rectangle.');
}

