noiseDetail.vi_du:
function khiBatDau() {
  taoKhung(100, 100);

  // Set the noise level and scale.
  let noiseLevel = 255;
  let noiseScale = 0.02;

  // Iterate from top to bottom.
  for (let y = 0; y < 100; y += 1) {
    // Iterate from left to right.
    for (let x = 0; x < 50; x += 1) {
      // Scale the input coordinates.
      let nx = noiseScale * x;
      let ny = noiseScale * y;

      // Compute the noise value with six octaves
      // and a low falloff factor.
      doChiTietNhieu(6, 0.25);
      let c = noiseLevel * nhieuPerlin(nx, ny);

      // Draw the left side.
      mauNet(c);
      veDiem(x, y);

      // Compute the noise value with four octaves
      // and a high falloff factor.
      doChiTietNhieu(4, 0.5);
      c = noiseLevel * nhieuPerlin(nx, ny);

      // Draw the right side.
      mauNet(c);
      veDiem(x + 50, y);
    }
  }

  moTa('Two gray cloudy patterns. The pattern on the right is cloudier than the pattern on the left.');
}

