  for (let i = 0; i < shuffledColors.length; i += 1) {
    // Calculate the x-coordinate.
    let x = (i + 1) * 12.5;

    // Style the circle.
    let c = shuffledColors[i];
    mauTo(c);

    // Draw the circle.
    veHinhTron(x, 67, 10);
  }

