httpDo.vi_du:
// Examples use USGS Earthquake API:
// https://earthquake.usgs.gov/fdsnws/event/1/#methods

// displays an animation of all USGS earthquakes
let earthquakes;
let eqFeatureIndex = 0;

function khiBatDau() {
 taoKhung(100,100);

  let url = 'https://earthquake.usgs.gov/fdsnws/event/1/query?format=geojson';

  const req = new Request(url, {
   method: 'GET',
   headers: {authorization: 'Bearer secretKey'}
 });
 // httpDo(path, method, datatype, success, error)

  thucHienHTTP(
    req,
    'GET',
   'json',
    res => {
     earthquakes = res;
    },
   err => {
     console.error('Error loading data:', err);
   }
 );
}

function khiVe() {
  // wait until the data is loaded
  if (!earthquakes || !earthquakes.features[eqFeatureIndex]) {
    return;
  }
  xoaManHinh();

  let feature = earthquakes.features[eqFeatureIndex];
  let doLon = feature.properties.doLon;
  let rad = doLon / 11 * ((doRong + doCao) / 2);
  mauTo(255, 0, 0, 100);
  veElip(doRong / 2 + ngauNhien(-2, 2), doCao / 2 + ngauNhien(-2, 2), rad, rad);

  if (eqFeatureIndex >= earthquakes.features.length) {
    eqFeatureIndex = 0;
  } else {
    eqFeatureIndex += 1;
  }
}

