createCamera.vi_du:
// Double-click to toggle between cameras.

let cam1;
let cam2;
let usingCam1 = true;

function khiBatDau() {
  taoKhung(100, 100, WEBGL);

  // Create the first camera.
  // Keep its default settings.
  cam1 = taoCamera();

  // Create the second camera.
  // Place it at the top-left.
  // Point it at the origin.
  cam2 = taoCamera();
  cam2.setPosition(400, -400, 800);
  cam2.lookAt(0, 0, 0);

  // Set the current camera to cam1.
  datCamera(cam1);

  moTa('A white cube on a gray background. The camera toggles between frontal and aerial views when the user double-clicks.');
}

function khiVe() {
  toMauNen(200);

  // Draw the box.
  veKhoiHop();
}

// Toggle the current camera when the user double-clicks.
function khiBamDupChuot() {
  if (usingCam1 === true) {
    datCamera(cam2);
    usingCam1 = false;
  } else {
    datCamera(cam1);
    usingCam1 = true;
  }
}

