// Double-click to squeeze the box.

let isSqueezed = false;

function khiBatDau() {
  taoKhung(100, 100, WEBGL);

  moTa('A white rectangular prism on a gray background. The box appears to become thinner when the user double-clicks.');
}

function khiVe() {
  toMauNen(200);

  // Place the camera at the top-right.
  maCamera(400, -400, 800);

  if (isSqueezed === true) {
    // Set fovy to 0.2.
    // Set aspect to 1.5.
    phoiCanh(0.2, 1.5);
  }

  // Draw the box.
  veKhoiHop();
}

