  isSqueezed = true;
}

ortho.vi_du:
function khiBatDau() {
  taoKhung(100, 100, WEBGL);

  moTa('A row of tiny, white cubes on a gray background. All the cubes appear the same size.');
}

function khiVe() {
  toMauNen(200);

  // Apply an orthographic projection.
  chieuTrucGiao();

  // Translate the origin toward the camera.
  dichChuyen(-10, 10, 600);

  // Rotate the coordinate system.
  xoayTrucY(-0.1);
  xoayTrucX(-0.1);

  // Draw the row of boxes.
  for (let i = 0; i < 6; i += 1) {
    dichChuyen(0, 0, -40);
    veKhoiHop(10);
  }
}

