function resetModel() {
  // If the p5.Geometry object has already been created,
  // free those resources.
  if (particles) {
    giaiPhongHinhKhoi(particles);
  }

  // Create a new p5.Geometry object with random spheres.
  particles = xayDungHinhKhoi(createParticles);
}

function createParticles() {
  for (let i = 0; i < 60; i += 1) {
    // Calculate random coordinates.
    let x = ngauNhienGauss(0, 20);
    let y = ngauNhienGauss(0, 20);
    let z = ngauNhienGauss(0, 20);

    luuTrangThai();
    // Translate to the particle's coordinates.
    dichChuyen(x, y, z);
    // Draw the particle.
    veHinhCau(5);
    phucHoiTrangThai();
  }
}

