worldToScreen.vi_du:
function khiBatDau() {
  taoKhung(150, 150);
  let vertices = [
    taoVector(-20, -20),
    taoVector(20, -20),
    taoVector(20, 20),
    taoVector(-20, 20)
  ];

  luuTrangThai();
  dichChuyen(75, 55);
  xoay(SO_PI / 4);

  // Convert world coordinates to screen coordinates
  let screenPos = vertices.bienDoi(v => toaDoTheGioiSangManHinh(v));
  phucHoiTrangThai();

  toMauNen(200);

  mauNet(0);
  mauTo(100, 150, 255, 100);
  batDauHinh();
  screenPos.forEach(pos => dinh(pos.x, pos.y));
  ketThucHinh(DONG);

  screenPos.forEach((pos, i) => {
    mauTo(0);
    coChuVanBan(10);
    if (i === 0) {
      veVanBan(i + 1, pos.x + 3, pos.y - 7);
    } else if (i === 1) {
      veVanBan(i + 1, pos.x + 7, pos.y + 2);
    } else if (i === 2) {
      veVanBan(i + 1, pos.x - 2, pos.y + 12);
    } else if (i === 3) {
      veVanBan(i + 1, pos.x - 12, pos.y - 2);
    }
  });

  mauTo(0);
  khongNet();
  coChuVanBan(10);
  let legendY = doCao - 35;
  screenPos.forEach((pos, i) => {
    veVanBan(`Vertex ${i + 1}: (${pos.x.toFixed(1)}, ${pos.y.toFixed(1)})`, 5, legendY + i * 10);
  });

  moTa('A rotating square is transformed and drawn using screen coordinates.');

}

